"""Smoothing, the B-spline fit, the dense verification and the route builder of the navigation core (overnight queue stage 2; navigation proposal N6, N7, section 5; decisions-log M129, M055).

    fine = FineRaster(obstacles, grid.origin, bounds)                   # the exact outlines rasterized at 1 cm, for the verification only (never for planning)
    r = plan_route(grid, fine, (x, y, yaw), (gx, gy, gyaw))              # r["ok"], r["reason"], r["samples"] (x, y, heading, curvature, s) along the route, r["turns"], r["lead_in_m"], ...

The route: a straight lead-out along the robot's heading (NAV_CFG["lead_out_m"]), the A* path (src/nav_planner.py), smoothed by the update rule of Nav2's SimpleSmoother (`w_data`, `w_smooth`) plus
one term Nav2 does not have, the push away from obstacles (`w_obs`), then a cubic B-spline through the points (scipy `splprep`: C2, so the curvature is continuous), and a straight lead-in ending at the
goal along its heading (`lead_in_m`, shorter down to `lead_in_min_m` if it does not fit). Before the robot moves, the spline is sampled every 2.5 cm of arc length and at every 2 degrees of heading
change; at each sample the real footprint at the tangent heading, grown by the tracking tolerance, is tested against the exact outlines. A failing stretch: the A* points around it are restored and
the spline refitted (up to 3 rounds, a wider stretch each time); if it still fails the whole route falls back to the unsmoothed A* polyline with stop-and-turn corners, each turn checked with the full
swept circle (the disc of radius r_out grown by the tolerance); a route that fails that too is "no verified path". An in-place turn at the start (no room for the lead-out) or at the goal (no
room for the lead-in) is only a fallback and only if its swept circle is clear (reasons: "can't line up").

Contents:
    FineRaster, resample, smooth, Spline, verify, plan_route.
"""

import math

import cv2
import numpy as np
from scipy import ndimage
from scipy.interpolate import splev, splprep

from src.nav_grid import rasterize_polygon
from src.nav_planner import astar
from src.task_config import NAV_CFG


def _get(e, name):
    return e[name] if isinstance(e, dict) else getattr(e, name, None)


class FineRaster:
    """The blocking outlines at 1 cm over the grid's bounds, and footprints grown by a tolerance as kernels, for the exact verification.

    Attributes:
        res (float): The cell edge, 0.01 m.
        origin (numpy.ndarray): World (x, y) of cell (0, 0)'s corner.
        mask (numpy.ndarray): Bool (ny, nx).
    """

    def __init__(self, obstacles, origin, shape_m, footprint, blocks=None, res=0.01):
        self.res, self.origin = float(res), np.asarray(origin, float)
        self.shape = (int(round(shape_m[1] / res)), int(round(shape_m[0] / res)))
        self.mask = np.zeros(self.shape, bool)
        for e in obstacles:
            if blocks is None or blocks(e):
                self.mask |= rasterize_polygon(np.asarray(_get(e, "outline"), float), self.origin, self.res, self.shape)
        self.footprint = np.asarray(footprint, float)
        self.r_out = float(np.hypot(self.footprint[:, 0], self.footprint[:, 1]).max())
        self._k = {}

    def _kernel(self, heading, grow):
        key = (round(math.degrees(heading) % 360.0 * 2) / 2, round(grow, 4))
        if key not in self._k:
            c, s = math.cos(heading), math.sin(heading)
            P = self.footprint @ np.array([[c, s], [-s, c]])
            half = int(math.ceil((self.r_out + grow) / self.res)) + 2
            n = 2 * half + 1
            K = rasterize_polygon(P, np.array([-half * self.res - 0.5 * self.res] * 2), self.res, (n, n)).astype(np.uint8)
            if grow > 0:
                r = int(round(grow / self.res))
                K = cv2.dilate(K, cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (2 * r + 1, 2 * r + 1)))
            self._k[key] = K.astype(bool)
        return self._k[key]

    def _disc(self, grow):
        key = ("disc", round(grow, 4))
        if key not in self._k:
            r = int(math.ceil((self.r_out + grow) / self.res))
            yy, xx = np.mgrid[-r:r + 1, -r:r + 1]
            self._k[key] = (np.hypot(xx, yy) * self.res <= self.r_out + grow)
        return self._k[key]

    def _hit(self, xy, K):
        half = K.shape[0] // 2
        ix, iy = int(math.floor((xy[0] - self.origin[0]) / self.res)), int(math.floor((xy[1] - self.origin[1]) / self.res))
        y0, y1, x0, x1 = iy - half, iy + half + 1, ix - half, ix + half + 1
        if y0 < 0 or x0 < 0 or y1 > self.shape[0] or x1 > self.shape[1]:
            return True
        return bool((self.mask[y0:y1, x0:x1] & K).any())

    def footprint_hit(self, xy, heading, grow=0.0):
        """Whether the footprint at a pose, grown by `grow` metres, overlaps an obstacle (the grid's border counts as an obstacle)."""
        return self._hit(xy, self._kernel(heading, grow))

    def turn_hit(self, xy, grow=0.0):
        """Whether the full swept circle of an in-place turn (the disc of radius r_out + grow) overlaps an obstacle."""
        return self._hit(xy, self._disc(grow))


def resample(points, step):
    """Points along a polyline `step` apart (the last point is the end of the polyline; the first is kept)."""
    P = np.asarray(points, float)
    seg = np.hypot(*np.diff(P, axis=0).T)
    s = np.concatenate([[0.0], np.cumsum(seg)])
    if s[-1] < 1e-9:
        return P[:1].copy()
    n = max(2, int(math.ceil(s[-1] / step)) + 1)
    t = np.linspace(0.0, s[-1], n)
    return np.stack([np.interp(t, s, P[:, 0]), np.interp(t, s, P[:, 1])], axis=1)


def smooth(points, fixed, grid, cfg=NAV_CFG):
    """The iterative smoother: y_i <- y_i + w_data (x_i - y_i) + w_smooth (y_{i-1} + y_{i+1} - 2 y_i) + w_obs * push away from obstacles (Nav2's SimpleSmoother plus the obstacle term).

    Args:
        points (numpy.ndarray): (N, 2) the resampled path.
        fixed (numpy.ndarray): Bool (N,): points that do not move (the ends and the lead-in and lead-out).
        grid (NavGrid): For the distance to the obstacles.
        cfg (dict): NAV_CFG.

    Returns:
        numpy.ndarray: (N, 2) the smoothed points.
    """
    X = np.asarray(points, float)
    Y = X.copy()
    free = ~np.asarray(fixed, bool)
    free[0] = free[-1] = False
    d_soft = max(cfg["inflation_radius_extra"], 1e-6)
    gy, gx = np.gradient(grid.dist, grid.res)
    for _ in range(int(cfg["smooth_max_its"])):
        idx = np.nonzero(free[1:-1])[0] + 1
        if not len(idx):
            break
        step = cfg["w_data"] * (X[idx] - Y[idx]) + cfg["w_smooth"] * (Y[idx - 1] + Y[idx + 1] - 2 * Y[idx])
        cx = (Y[idx, 0] - grid.origin[0]) / grid.res - 0.5
        cy = (Y[idx, 1] - grid.origin[1]) / grid.res - 0.5
        d = ndimage.map_coordinates(grid.dist, [cy, cx], order=1, mode="nearest")
        gradv = np.stack([ndimage.map_coordinates(gx, [cy, cx], order=1, mode="nearest"), ndimage.map_coordinates(gy, [cy, cx], order=1, mode="nearest")], axis=1)
        gn = np.maximum(np.hypot(gradv[:, 0], gradv[:, 1]), 1e-9)[:, None]
        push = np.maximum(0.0, d_soft - np.maximum(d - grid.r_in, 0.0))[:, None] / d_soft * (gradv / gn)
        step = step + cfg["w_obs"] * grid.res * push
        Y[idx] += step
        if float(np.abs(step).max()) < cfg["smooth_tol_m"]:
            break
    return Y


class Spline:
    """A cubic B-spline through points (scipy splprep), sampled by arc length.

    Attributes:
        length (float): The arc length, metres.
    """

    def __init__(self, points, cfg=NAV_CFG, weights=None):
        P = np.asarray(points, float)
        k = 3 if len(P) > 3 else len(P) - 1
        self.tck, _ = splprep([P[:, 0], P[:, 1]], k=k, s=cfg["spline_s_per_point"] * len(P), w=weights)
        u = np.linspace(0.0, 1.0, max(400, 20 * len(P)))
        xy = np.stack(splev(u, self.tck), axis=1)
        s = np.concatenate([[0.0], np.cumsum(np.hypot(*np.diff(xy, axis=0).T))])
        self._u, self._s, self.length = u, s, float(s[-1])

    def at(self, s):
        """(x, y, heading, curvature) at arc lengths s (array)."""
        u = np.interp(np.asarray(s, float), self._s, self._u)
        x, y = splev(u, self.tck)
        dx, dy = splev(u, self.tck, der=1)
        ddx, ddy = splev(u, self.tck, der=2)
        kappa = (dx * ddy - dy * ddx) / np.maximum(np.hypot(dx, dy), 1e-9) ** 3
        return np.stack([x, y, np.arctan2(dy, dx), kappa], axis=1)

    def samples(self, cfg=NAV_CFG):
        """Samples every verify_step_m of arc length and finer where the heading changes faster than verify_heading_deg per sample: (N, 5) x, y, heading, curvature, s."""
        ds = float(cfg["verify_step_m"])
        s = np.arange(0.0, self.length, ds / 4)
        h = np.unwrap(self.at(s)[:, 2])
        keep, last_s, last_h = [0], 0.0, h[0]
        lim = math.radians(cfg["verify_heading_deg"])
        for i in range(1, len(s)):
            if s[i] - last_s >= ds - 1e-9 or abs(h[i] - last_h) >= lim:
                keep.append(i)
                last_s, last_h = s[i], h[i]
        if keep[-1] != len(s) - 1:
            keep.append(len(s) - 1)
        s = np.append(s[keep], self.length) if s[keep][-1] < self.length - 1e-9 else s[keep]
        return np.column_stack([self.at(s), s])


def verify(samples, fine, cfg=NAV_CFG):
    """The samples' footprints (grown by the tracking tolerance) against the exact outlines: a bool array, True where the footprint hits something."""
    return np.array([fine.footprint_hit(sm[:2], sm[2], cfg["track_tol"]) for sm in samples])


def _wrap(a):
    return (a + math.pi) % (2 * math.pi) - math.pi


def _straight_clear(fine, p0, p1, heading, cfg):
    n = max(2, int(math.ceil(float(np.hypot(*(np.asarray(p1) - np.asarray(p0)))) / cfg["verify_step_m"])) + 1)
    return not any(fine.footprint_hit(p0 + (p1 - p0) * t, heading, cfg["track_tol"]) for t in np.linspace(0.0, 1.0, n))


def _polyline_route(path, fine, cfg):
    """The unsmoothed fallback: the A* polyline with stop-and-turn corners, every straight segment verified at its heading and every turn with the full swept circle."""
    P = resample(path, cfg["verify_step_m"] * 2)
    corners = [0]
    seg_h = [math.atan2(*(P[i + 1] - P[i])[::-1]) for i in range(len(P) - 1)]
    turns = []
    for i in range(1, len(seg_h)):
        if abs(_wrap(seg_h[i] - seg_h[i - 1])) > math.radians(10.0):
            turns.append({"at": P[i].tolist(), "from": seg_h[i - 1], "to": seg_h[i], "clear": not fine.turn_hit(P[i], cfg["track_tol"])})
    samples = []
    s = 0.0
    for i in range(len(P) - 1):
        samples.append([P[i, 0], P[i, 1], seg_h[i], 0.0, s])
        s += float(np.hypot(*(P[i + 1] - P[i])))
    samples.append([P[-1, 0], P[-1, 1], seg_h[-1], 0.0, s])
    samples = np.array(samples)
    bad = verify(samples, fine, cfg)
    ok = not bad.any() and all(t["clear"] for t in turns)
    return ok, samples, turns


def _stretch_angle(P, heading, first, reach=0.3):
    """The angle between a heading and the direction of the first (or last) `reach` metres of a path."""
    Q = P if first else P[::-1]
    d = np.hypot(*(Q - Q[0]).T)
    j = int(np.argmax(d >= reach)) if (d >= reach).any() else len(Q) - 1
    v = Q[j] - Q[0]
    if float(np.hypot(*v)) < 1e-9:
        return 0.0
    a = math.atan2(v[1], v[0]) + (0.0 if first else math.pi)
    return abs(_wrap(a - heading))


def plan_route(grid, fine, start, goal, cfg=NAV_CFG):
    """Plans, smooths, fits and verifies a route from a start pose to a goal pose.

    The lead-in lengths are tried longest first (lead_in_m down to lead_in_min_m, the straight stretch itself must be clear), then the checked in-place turn at the goal; the first whose whole route
    (A*, smoothing, spline, dense verification) verifies is used, so a lead-in that fits as a straight stretch but leaves no room for the curve into it gives way to a shorter one.

    Args:
        grid (NavGrid): The planning grid (built from the world model).
        fine (FineRaster): The exact outlines at 1 cm.
        start (tuple): (x, y, yaw) of the robot.
        goal (tuple): (x, y, yaw): the approach spot and the stance heading.
        cfg (dict): NAV_CFG.

    Returns:
        dict: "ok", "reason" ("" or "start blocked", "goal blocked", "no path", "can't line up", "start cannot turn", "no verified path"), "samples" (N, 5: x, y, heading, curvature, s),
        "turns" (in-place turns: {"at", "from", "to", "clear"}), "lead_in_m" (the length used, 0 if none), "lead_out_m", "smoothed" (False for the polyline fallback), "repairs" (rounds of local refit),
        "max_curvature", "length", "astar" (the planner's result).
    """
    gx, gy, gyaw = goal
    p_g = np.array([gx, gy])
    gdir = np.array([math.cos(gyaw), math.sin(gyaw)])
    cands, L = [], cfg["lead_in_m"]
    while L >= cfg["lead_in_min_m"] - 1e-9:
        if _straight_clear(fine, p_g - gdir * L, p_g, gyaw, cfg):
            cands.append(L)
        L -= 0.1
    if not fine.turn_hit(p_g, cfg["track_tol"]):
        cands.append(0.0)
    if not cands:
        return _empty("can't line up")
    last = None
    for lead_in in cands:
        r = _route(grid, fine, start, goal, lead_in, cfg)
        if r["ok"] or r["reason"] in ("start blocked", "goal blocked", "no path", "start cannot turn"):
            return r
        last = r
    return last


def _empty(reason):
    return {"ok": False, "reason": reason, "samples": None, "turns": [], "lead_in_m": 0.0, "lead_out_m": 0.0, "smoothed": True, "repairs": 0, "max_curvature": 0.0, "length": 0.0, "astar": None}


def _route(grid, fine, start, goal, lead_in, cfg):
    """One route for a given lead-in length (0: the in-place turn at the goal): the lead-out, A*, smoothing, spline, verification, and the polyline fallback."""
    sx, sy, syaw = start
    gx, gy, gyaw = goal
    res = _empty("")
    tol = cfg["track_tol"]
    p_s, p_g = np.array([sx, sy]), np.array([gx, gy])
    gdir = np.array([math.cos(gyaw), math.sin(gyaw)])
    sdir = np.array([math.cos(syaw), math.sin(syaw)])
    lead_out, L = 0.0, cfg["lead_out_m"]
    while L >= 0.1 - 1e-9:
        if _straight_clear(fine, p_s, p_s + sdir * L, syaw, cfg):
            lead_out = L
            break
        L -= 0.1
    lim = math.radians(cfg["turn_in_place_deg"])
    for _ in range(2):                                                # a path leaving the lead-out's heading by more than the limit would have a cusp: a turn at the start instead
        a_goal = p_g - gdir * lead_in
        a_start = p_s + sdir * lead_out
        ar = astar(grid, a_start, a_goal, cfg)
        res["astar"] = {k: ar[k] for k in ("ok", "reason", "expanded", "cost")}
        if not ar["ok"]:
            res["reason"] = ar["reason"]
            return res
        P = np.asarray(ar["path"], float)
        if lead_out > 0 and _stretch_angle(P, syaw, first=True) > lim:
            lead_out = 0.0
            continue
        break
    if lead_in > 0 and _stretch_angle(P, gyaw, first=False) > lim:     # arriving the wrong way round: this lead-in would make a cusp; the next candidate (a shorter one, or the turn) is tried
        res["reason"] = "no verified path"
        return res
    turns = []
    if lead_in == 0.0:
        turns.append({"at": p_g.tolist(), "from": None, "to": gyaw, "clear": True, "where": "goal"})
    if lead_out == 0.0:
        if fine.turn_hit(p_s, tol):
            res["reason"] = "start cannot turn"
            return res
        turns.append({"at": p_s.tolist(), "from": syaw, "to": None, "clear": True, "where": "start"})
    core = [np.asarray(p) for p in ar["path"]]
    poly = ([p_s] if lead_out > 0 else []) + core + ([p_g] if lead_in > 0 else [])
    if lead_out == 0:
        poly[0] = p_s
    pts = resample(np.array(poly), grid.res)
    fixed = np.zeros(len(pts), bool)
    for i, p in enumerate(pts):
        if (lead_out > 0 and float(np.hypot(*(p - p_s))) <= lead_out + 1e-6) or (lead_in > 0 and float(np.hypot(*(p - p_g))) <= lead_in + 1e-6):
            fixed[i] = True
    fixed[0] = fixed[-1] = True
    sm = smooth(pts, fixed, grid, cfg)
    weights = np.where(fixed, 20.0, 1.0)
    cur = sm.copy()
    ok = False
    for rnd in range(4):
        spl = Spline(cur, cfg, weights)
        smp = spl.samples(cfg)
        bad = verify(smp, fine, cfg)
        if not bad.any():
            ok = True
            break
        if rnd == 3:
            break
        radius = 0.5 * (rnd + 1)
        for b in np.nonzero(bad)[0]:                                   # restore the A* points around the failing sample
            near = np.hypot(*(pts - smp[b, :2]).T) <= radius
            cur[near & ~fixed] = pts[near & ~fixed]
        res["repairs"] = rnd + 1
    if ok:
        res.update(ok=True, samples=smp, lead_in_m=lead_in, lead_out_m=lead_out, turns=turns, length=spl.length, max_curvature=float(np.abs(smp[:, 3]).max()), smoothed=True)
        return res
    okp, smp, tr = _polyline_route([p_s] + core + [p_g], fine, cfg)
    res.update(smoothed=False, samples=smp, turns=turns + tr, lead_in_m=lead_in, lead_out_m=lead_out, length=float(smp[-1, 4]))
    if okp and all(t["clear"] for t in res["turns"]):
        res["ok"] = True
    else:
        res["reason"] = "no verified path"
    return res
